import { useEffect, useRef, useState } from "react";
import { useAuth } from "../auth/AuthProvider";
import { useAuthFetch } from "../auth/authFetch";
import { sampleUrl } from "../auth/config";
import { Icon } from "./Icon";
import { SampleLabel } from "./SampleLabel";

type Phase = "idle" | "loading" | "playing";

interface ReadAloudButtonProps {
  /** Text sent to the read-aloud service when signed in. */
  text: string;
  /** Pre-generated recording of the same text in `public/samples/`, used when signed out. */
  sampleFile: string;
}

/**
 * Signed in: plays audio generated by `POST /v1/read-aloud`.
 * Signed out, or if the service fails: plays the pre-generated sample, clearly labelled.
 */
export function ReadAloudButton({ text, sampleFile }: ReadAloudButtonProps) {
  const { isAuthenticated } = useAuth();
  const authFetch = useAuthFetch();
  const [phase, setPhase] = useState<Phase>("idle");
  const [isSample, setIsSample] = useState(false);
  const [notice, setNotice] = useState<string | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const objectUrlRef = useRef<string | null>(null);

  const releaseAudio = () => {
    audioRef.current?.pause();
    audioRef.current = null;
    if (objectUrlRef.current) URL.revokeObjectURL(objectUrlRef.current);
    objectUrlRef.current = null;
  };

  useEffect(() => releaseAudio, []);

  const play = async (src: string, sample: boolean) => {
    const audio = new Audio(src);
    audioRef.current = audio;
    audio.onended = () => setPhase("idle");
    setIsSample(sample);
    try {
      await audio.play();
      setPhase("playing");
    } catch {
      setPhase("idle");
      setNotice("Your browser blocked audio playback.");
    }
  };

  const start = async () => {
    releaseAudio();
    setNotice(null);
    setPhase("loading");

    if (isAuthenticated) {
      const result = await authFetch<Blob>(
        "/v1/read-aloud",
        {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ text }),
        },
        (res) => res.blob(),
      );
      if (result.status === "ok") {
        objectUrlRef.current = URL.createObjectURL(result.data);
        return play(objectUrlRef.current, false);
      }
      setNotice(
        result.status === "signin"
          ? result.message
          : `Read-aloud isn’t available right now (${result.message}). Playing a sample instead.`,
      );
    }
    return play(sampleUrl(sampleFile), true);
  };

  const stop = () => {
    releaseAudio();
    setPhase("idle");
  };

  return (
    <div className="read-aloud">
      <button
        type="button"
        className="read-aloud-button"
        onClick={phase === "playing" ? stop : start}
        disabled={phase === "loading"}
        aria-pressed={phase === "playing"}
      >
        <Icon name={phase === "playing" ? "x" : "spark"} size={16} />
        {phase === "loading" ? "Preparing audio…" : phase === "playing" ? "Stop" : "Read aloud"}
      </button>
      {isSample && phase === "playing" && <SampleLabel>Sample audio</SampleLabel>}
      {!isAuthenticated && phase === "idle" && (
        <small>Plays a sample recording. Sign in to hear any text read aloud.</small>
      )}
      {notice && <small role="status">{notice}</small>}
    </div>
  );
}
